compile.workshop:
variables {
    global:
        0: g
}

//Optimize for size enabled
rule ("skip counts") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip If(Compare(Global.g, ==, 1), 3);
        Set Global Variable(g, 5);
        Set Global Variable(g, 6);
        Set Global Variable(g, 7);
        "pass"
        disabled Abort;
        Skip If(Compare(Global.g, ==, 3), True);
        Set Global Variable(g, 8);
    }
}

//Optimizations disabled
rule ("skip zero without optimization") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip If(Compare(Global.g, ==, 4), 0);
        Set Global Variable(g, 9);
    }
}

